package com.spms.controller;
import lombok.RequiredArgsConstructor;import org.springframework.security.core.Authentication;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.bind.annotation.*;import com.spms.entity.*;import com.spms.repository.*;import java.time.*;import java.util.*;
@RestController @RequiredArgsConstructor public class OwnerController{private final AdminAccessRequestRepository requests;private final UserAccountRepository users;private final PasswordEncoder encoder;
 @PostMapping("/api/admin-access-requests")public AdminAccessRequest request(@RequestBody AdminAccessRequest r){r.setId(null);r.setStatus(AdminAccessRequest.Status.PENDING);r.setRequestedAt(LocalDateTime.now());r.setReviewedAt(null);r.setReviewedBy(null);return requests.save(r);}
 @GetMapping("/api/owner/admin-access-requests")public List<AdminAccessRequest> list(){return requests.findAllByOrderByRequestedAtDesc();}
 @PostMapping("/api/owner/admin-access-requests/{id}/{decision}")public AdminAccessRequest decide(@PathVariable UUID id,@PathVariable String decision,@RequestParam(required=false)String username,@RequestParam(required=false)String temporaryPassword,Authentication a){var r=requests.findById(id).orElseThrow();if(r.getStatus()!=AdminAccessRequest.Status.PENDING)throw new IllegalArgumentException("Request already reviewed");r.setReviewedBy(users.findByUsername(a.getName()).orElseThrow());r.setReviewedAt(LocalDateTime.now());if(decision.equals("approve")){if(username==null||username.isBlank())throw new IllegalArgumentException("Admin username is required");if(temporaryPassword==null||temporaryPassword.length()<8)throw new IllegalArgumentException("Temporary password must contain at least 8 characters");if(users.findByUsername(username.trim().toLowerCase()).isPresent())throw new IllegalArgumentException("That username already exists. Choose another username.");var u=new UserAccount();u.setUsername(username.trim().toLowerCase());u.setPasswordHash(encoder.encode(temporaryPassword));u.setRole(UserAccount.Role.ADMIN);users.save(u);r.setStatus(AdminAccessRequest.Status.APPROVED);}else if(decision.equals("reject"))r.setStatus(AdminAccessRequest.Status.REJECTED);else throw new IllegalArgumentException("Invalid decision");return requests.save(r);}}
